"use client"

import { useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

export type FormCardField =
  | { name: string; label: string; type: "text" | "date" | "textarea"; required?: boolean; placeholder?: string }
  | { name: string; label: string; type: "number"; required?: boolean; placeholder?: string; min?: number; max?: number }
  | { name: string; label: string; type: "select"; required?: boolean; options: { label: string; value: string }[] }
  | { name: string; label: string; type: "toggle"; required?: boolean }

export type FormCardProps = {
  title: string
  description?: string
  submitLabel?: string
  fields: FormCardField[]
  isLoading?: boolean
  isDisabled?: boolean
  error?: {
    title: string
    description?: string
  }
  onSubmit?: (values: Record<string, string | number | boolean>) => void
}

export function FormCard({
  title,
  description,
  submitLabel = "Submit",
  fields,
  isLoading,
  isDisabled,
  error,
  onSubmit,
}: FormCardProps) {
  const initialValues = useMemo(() => {
    return Object.fromEntries(fields.map((field) => [field.name, field.type === "toggle" ? false : ""]))
  }, [fields])
  const [values, setValues] = useState<Record<string, string | number | boolean>>(initialValues)

  function setValue(name: string, value: string | number | boolean) {
    setValues((current) => ({ ...current, [name]: value }))
  }

  return (
    <Card className="w-full max-w-2xl" data-fable-ui="form-card" aria-busy={isLoading || undefined}>
      <CardHeader>
        <CardTitle className="text-base">{title || "Collect input"}</CardTitle>
        {description ? <CardDescription>{description}</CardDescription> : null}
      </CardHeader>
      <CardContent>
        {isLoading ? <p className="text-sm text-muted-foreground">Preparing form...</p> : null}
        {error ? (
          <div className="mb-4 rounded-md border border-destructive/20 bg-destructive/5 p-3">
            <p className="text-sm font-medium text-destructive">{error.title}</p>
            {error.description ? <p className="text-sm text-muted-foreground">{error.description}</p> : null}
          </div>
        ) : null}
        <form
          className="flex flex-col gap-4"
          onSubmit={(event) => {
            event.preventDefault()
            onSubmit?.(values)
          }}
        >
          {fields.map((field) => {
            const value = values[field.name]

            return (
              <label key={field.name} className={cn("flex flex-col gap-2 text-sm font-medium", {
                "flex-row-reverse items-center justify-end": field.type === "toggle"
              })}>
                <span>{field.label}</span>
                {field.type === "textarea" ? (
                  <Textarea
                    value={String(value ?? "")}
                    placeholder={field.placeholder}
                    required={field.required}
                    disabled={isDisabled}
                    onChange={(event) => setValue(field.name, event.target.value)}
                  />
                ) : field.type === "select" ? (
                  <select
                    className="h-9 rounded-md border bg-background px-3 text-sm"
                    value={String(value ?? "")}
                    required={field.required}
                    disabled={isDisabled}
                    onChange={(event) => setValue(field.name, event.target.value)}
                  >
                    <option value="">Select...</option>
                    {field.options.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                ) : field.type === "toggle" ? (
                  <input
                    type="checkbox"
                    checked={Boolean(value)}
                    disabled={isDisabled}
                    onChange={(event) => setValue(field.name, event.target.checked)}
                  />
                ) : (
                  <Input
                    type={field.type}
                    value={String(value ?? "")}
                    min={field.type === "number" ? field.min : undefined}
                    max={field.type === "number" ? field.max : undefined}
                    placeholder={field.placeholder}
                    required={field.required}
                    disabled={isDisabled}
                    onChange={(event) =>
                      setValue(
                        field.name,
                        field.type === "number" ? Number(event.target.value) : event.target.value,
                      )
                    }
                  />
                )}
              </label>
            )
          })}
          <CardFooter className="px-0 pb-0">
            <Button type="submit" disabled={isDisabled || fields.length === 0}>
              {submitLabel}
            </Button>
          </CardFooter>
        </form>
      </CardContent>
    </Card>
  )
}

import { tool } from "ai"
import { z } from "zod"

import { defineFableComponent } from "@/lib/fable-ui/core/definitions"
import { FormCard } from "@/components/fable-ui/form-card/form-card"

const baseField = z.object({
  name: z.string().min(1),
  label: z.string().min(1),
  required: z.boolean().optional(),
  placeholder: z.string().optional(),
})

export const collectInputSchema = z.object({
  title: z.string().min(1),
  description: z.string().optional(),
  submitLabel: z.string().min(1).optional(),
  fields: z
    .array(
      z.discriminatedUnion("type", [
        baseField.extend({ type: z.literal("text") }),
        baseField.extend({ type: z.literal("date") }),
        baseField.extend({ type: z.literal("textarea") }),
        baseField.extend({ type: z.literal("number"), min: z.number().optional(), max: z.number().optional() }),
        baseField.extend({
          type: z.literal("select"),
          options: z.array(z.object({ label: z.string().min(1), value: z.string().min(1) })).min(1).max(12),
        }),
        baseField.extend({ type: z.literal("toggle") }),
      ]),
    )
    .min(1)
    .max(8),
})

export type CollectInput = z.infer<typeof collectInputSchema>

export function createCollectInputTool() {
  return tool({
    description:
      "Collect a few structured fields mid-conversation. Keep forms short; the server must validate submitted values.",
    inputSchema: collectInputSchema,
    execute: async (input) => input,
  })
}

export const collectInput = defineFableComponent({
  name: "collect_input",
  schema: collectInputSchema,
  tool: createCollectInputTool(),
  renderer: {
    Component: FormCard,
    loadingProps: { title: "Collect input", fields: [], isLoading: true },
    emptyProps: { title: "Collect input", fields: [] },
    errorProps: (description: string) => ({
      title: "Form unavailable",
      fields: [],
      error: { title: "Form unavailable", description },
    }),
    toProps: (data: CollectInput, handlers) => ({ ...data, onSubmit: handlers.onFormSubmit }),
  },
})
